    1) requestAnimationFrame loop with fixed-step physics
    ```js
    // main.js
    import { updatePhysics } from './core/physics.js';
    import { renderFrame, resizeIfNeeded } from './render/canvasRenderer.js';
    import { getState } from './core/state.js';

    const FIXED_DT = 1 / 60;   // simulation seconds per physics step
    const MAX_STEPS = 8;
    let lastRealT = performance.now() / 1000;
    let accumulator = 0;

    function frame() {
      const state = getState();
      const now = performance.now() / 1000;
      let realDt = now - lastRealT;
      lastRealT = now;

      realDt = Math.min(realDt, 0.25);         // clamp on tab switch
      accumulator += realDt * state.timeScale; // speed multiplier

      let steps = 0;
      while (accumulator >= FIXED_DT && steps < MAX_STEPS) {
        updatePhysics(FIXED_DT);
        accumulator -= FIXED_DT;
        steps++;
      }

      resizeIfNeeded();
      const alpha = accumulator / FIXED_DT;    // interpolation factor (optional)
      renderFrame(alpha);

      requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
    ```

    2) DPR-aware canvas setup (scene + labels)
    ```js
    // render/canvasRenderer.js
    import tinycolor from 'tinycolor2';
    import { worldToScreen, getView } from './scale.js';
    import { getBodies } from '../data/bodies.js'; // [{ id, name, pos:[x,y] in AU, radiusKm, color }]

    const sceneCanvas = document.getElementById('sceneCanvas');
    const labelCanvas = document.getElementById('labelCanvas');
    const sceneCtx = sceneCanvas.getContext('2d');
    const labelCtx = labelCanvas.getContext('2d', { alpha: true });

    let lastDpr = 0, lastCssW = 0, lastCssH = 0;

    export function resizeIfNeeded() {
      const dpr = window.devicePixelRatio || 1;
      const cssW = sceneCanvas.clientWidth || sceneCanvas.offsetWidth || window.innerWidth;
      const cssH = sceneCanvas.clientHeight || sceneCanvas.offsetHeight || window.innerHeight;

      if (dpr !== lastDpr || cssW !== lastCssW || cssH !== lastCssH) {
        [sceneCanvas, labelCanvas].forEach(c => {
          c.width  = Math.max(1, Math.floor(cssW * dpr));
          c.height = Math.max(1, Math.floor(cssH * dpr));
          c.style.width = cssW + 'px';
          c.style.height = cssH + 'px';
          const ctx = c.getContext('2d');
          ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // 1 CSS px = 1 unit in drawing ops
        });
        lastDpr = dpr; lastCssW = cssW; lastCssH = cssH;
      }
    }

    export function renderFrame(alpha = 0) {
      const { zoom, pan } = getView();
      const bodies = getBodies();

      // Clear
      sceneCtx.clearRect(0, 0, sceneCanvas.width, sceneCanvas.height);
      labelCtx.clearRect(0, 0, labelCanvas.width, labelCanvas.height);

      // Draw Sun glow (example)
      const sunScreen = worldToScreen([0,0]);
      const glow = sceneCtx.createRadialGradient(sunScreen[0], sunScreen[1], 0, sunScreen[0], sunScreen[1], 120);
      glow.addColorStop(0, 'rgba(255,230,120,0.9)');
      glow.addColorStop(1, 'rgba(255,230,120,0.0)');
      sceneCtx.fillStyle = glow;
      sceneCtx.beginPath();
      sceneCtx.arc(sunScreen[0], sunScreen[1], 120, 0, Math.PI*2);
      sceneCtx.fill();

      // Draw planets (very simplified)
      for (const b of bodies) {
        const p = worldToScreen(b.pos); // AU -> screen px via scale.js
        sceneCtx.fillStyle = b.color;
        sceneCtx.beginPath();
        const visR = Math.max(2, Math.sqrt(b.radiusKm) * 0.03); // nonlinear sizing
        sceneCtx.arc(p[0], p[1], visR, 0, Math.PI*2);
        sceneCtx.fill();
      }
    }
    ```

    3) Basic hit-testing and label collision using rbush
    ```js
    // render/labelManager.js
    import RBush from 'rbush';
    import { worldToScreen } from './scale.js';

    const tree = new RBush(); // stores {minX, minY, maxX, maxY, id, text, x, y}

    export function layoutAndDrawLabels(ctx, bodies, opts = {}) {
      const {
        font = '12px system-ui',
        padding = 2,
        minPxSize = 4,
        color = '#ccd6f6',
        halo = 'rgba(0,0,0,0.6)'
      } = opts;

      tree.clear();
      ctx.font = font;
      ctx.textBaseline = 'middle';

      for (const b of bodies) {
        const s = worldToScreen(b.pos);
        if (!s) continue;

        // Skip very small on-screen bodies (LOD)
        const pxR = Math.max(2, Math.sqrt(b.radiusKm) * 0.03);
        if (pxR < minPxSize) continue;

        const text = b.name || b.id;
        const metrics = ctx.measureText(text);
        const w = Math.ceil(metrics.width);
        const h = 14; // approx line height for 12px

        const x = s[0] + pxR + 6; // offset label to the right
        const y = s[1];

        const aabb = { minX: x - padding, minY: y - h/2 - padding, maxX: x + w + padding, maxY: y + h/2 + padding, id: b.id, text, x, y, w, h };

        // Collision check
        const collisions = tree.search(aabb);
        if (collisions.length === 0) {
          tree.insert(aabb);
          // Draw halo
          ctx.fillStyle = halo;
          ctx.fillRect(aabb.minX, aabb.minY, (aabb.maxX - aabb.minX), (aabb.maxY - aabb.minY));
          // Draw text
          ctx.fillStyle = color;
          ctx.fillText(text, x, y);
        }
      }
    }
    ```

    4) Basic screen-space hit-testing for selection
    ```js
    // ui/picker.js
    import { worldToScreen } from '../render/scale.js';
    import { getBodies } from '../data/bodies.js';

    export function setupPicker(canvas, onPick) {
      canvas.addEventListener('click', (e) => {
        const rect = canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        const bodies = getBodies();
        let best = null;
        let bestDist2 = Infinity;

        for (const b of bodies) {
          const p = worldToScreen(b.pos);
          if (!p) continue;
          const visR = Math.max(2, Math.sqrt(b.radiusKm) * 0.03);
          const dx = x - p[0];
          const dy = y - p[1];
          const d2 = dx*dx + dy*dy;
          const pickR = visR + 6; // tolerance
          if (d2 <= pickR*pickR && d2 < bestDist2) {
            best = b;
            bestDist2 = d2;
          }
        }

        if (best) onPick(best);
      }, { passive: true });
    }
    ```

