def validate_text_payload(text: Optional[str]) -> Optional[str]:
    if not text or not text.strip():
        return "Please paste some recipe text."
    # size check: approximate to 50k chars (~50 KB)
    if len(text) > 50_000:
        return "Pasted text is too large (limit ~50 KB)."
    return None

def validate_file_storage(fs) -> Optional[str]:
    if fs is None or fs.filename is None or fs.filename.strip() == "":
        return "Please choose a .txt or .pdf file."
    filename = fs.filename
    _, ext = os.path.splitext(filename.lower())
    if ext not in ALLOWED_EXTS:
        return "Invalid file type. Please upload a .txt or .pdf file."
    # Peek content type if provided
    ctype = fs.mimetype or ""
    if ext == ".txt" and (ctype and ctype not in ALLOWED_TEXT_MIMES and not ctype.startswith("text/")):
        # Allow text/* as many browsers set text/plain or text/whatever
        return "Invalid text file content type."
    if ext == ".pdf" and ctype and ctype != "application/pdf":
        # Some browsers may omit exact match; we still enforce extension
        pass
    # Size is enforced globally by MAX_CONTENT_LENGTH; still, we can early read size
    fs.stream.seek(0, io.SEEK_END)
    size = fs.stream.tell()
    fs.stream.seek(0)
    if size > app.config["MAX_CONTENT_LENGTH"]:
        return "File is too large (max 2 MB)."
    return None

def build_results_from_text(text: str):
    ings = extract_ingredients_from_text(text, limit=12)
    if not ings:
        return None, None, "We couldn't find any ingredients in the provided text."
    lore = {}
    for ing in ings:
        try:
            lore[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception as e:
            logger.warning(f"Lookup failed for {ing}: {e}")
            lore[ing] = {"ingredient": ing, "adjectives": [], "related": [], "wikipedia_summary": "", "wikidata_description": ""}
    spell = build_spell(ings, lore)
    return ings, lore, None

@app.route("/process_text", methods=["POST"])
def process_text():
    text = request.form.get("recipe_text", "")
    err = validate_text_payload(text)
    if err:
        return make_response(render_error(err), 400)

    try:
        ingredients, lore_map, msg = build_results_from_text(text)
        if msg:
            return make_response(render_error(msg), 422)
        return make_response(render_result(ingredients, lore_map, build_spell(ingredients, lore_map)), 200)
    except Exception as e:
        logger.exception("Failed to process pasted text")
        return make_response(render_error("Unexpected error while processing text. Please try again."), 500)

@app.route("/process_file", methods=["POST"])
def process_file():
    if "recipe_file" not in request.files:
        return make_response(render_error("No file part in the request."), 400)
    fs = request.files["recipe_file"]
    ferr = validate_file_storage(fs)
    if ferr:
        return make_response(render_error(ferr), 400)

    filename = fs.filename
    _, ext = os.path.splitext(filename.lower())
    try:
        data = fs.read()
        if not data:
            return make_response(render_error("The uploaded file appears to be empty."), 400)
        if len(data) > app.config["MAX_CONTENT_LENGTH"]:
            return make_response(render_error("File is too large (max 2 MB)."), 400)

        if ext == ".txt":
            try:
                # Try utf-8 first, then fallback latin-1
                try:
                    text = data.decode("utf-8")
                except UnicodeDecodeError:
                    text = data.decode("latin-1")
            except Exception:
                return make_response(render_error("Could not read the text file. Please upload a valid .txt file."), 400)
        elif ext == ".pdf":
            try:
                text = extract_text_from_pdf(data)
            except RuntimeError as e:
                return make_response(render_error(str(e)), 400)
            except Exception:
                return make_response(render_error("Failed to parse the PDF file."), 400)
        else:
            return make_response(render_error("Unsupported file type. Please upload .txt or .pdf."), 400)

        ingredients, lore_map, msg = build_results_from_text(text)
        if msg:
            return make_response(render_error(msg), 422)
        return make_response(render_result(ingredients, lore_map, build_spell(ingredients, lore_map)), 200)

    except Exception as e:
        logger.exception("Failed to process file")
        return make_response(render_error("Unexpected error while processing the file. Please try again."), 500)

