"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  collection,
  onSnapshot,
  orderBy,
  query,
  serverTimestamp,
  setDoc,
  doc,
} from "firebase/firestore";
import { db } from "@/lib/firebase";

type DocItem = {
  id: string;
  title?: string;
  updatedAt?: any;
  createdAt?: any;
  tags?: string[];
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocsPage() {
  const [docs, setDocs] = useState<DocItem[]>([]);
  const [title, setTitle] = useState("");
  const [customSlug, setCustomSlug] = useState("");
  const [creating, setCreating] = useState(false);
  const [qText, setQText] = useState("");
  const router = useRouter();

  useEffect(() => {
    const q = query(collection(db, "docs"), orderBy("updatedAt", "desc"));
    const unsub = onSnapshot(q, (snap) => {
      const items: DocItem[] = [];
      snap.forEach((d) => items.push({ id: d.id, ...(d.data() as any) }));
      setDocs(items);
    });
    return () => unsub();
  }, []);

  const computedSlug = useMemo(() => {
    return customSlug ? slugify(customSlug) : slugify(title);
  }, [title, customSlug]);

  const filtered = useMemo(() => {
    const t = qText.toLowerCase();
    if (!t) return docs;
    return docs.filter((d) => {
      const hay = `${d.title || d.id} ${(d.tags || []).join(" ")}`.toLowerCase();
      return hay.includes(t);
    });
  }, [docs, qText]);

  const onCreate = async () => {
    const slug = computedSlug;
    if (!slug) return;
    setCreating(true);
    try {
      const ref = doc(db, "docs", slug);
      const now = serverTimestamp();
      await setDoc(
        ref,
        {
          title: title || slug,
          content: `# ${title || slug}\n\nStart writing your documentation here...`,
          tags: [],
          createdAt: now,
          updatedAt: now,
        },
        { merge: true }
      );
      router.push(`/docs/${slug}`);
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="mx-auto max-w-5xl p-6">
      <div className="mb-8">
        <h1 className="text-3xl font-semibold tracking-tight">Documentation</h1>
        <p className="text-sm text-muted-foreground">
          Manage multiple markdown-based docs with live updates from Firebase.
        </p>
      </div>

      <div className="rounded-lg border bg-card p-4 shadow-sm mb-6">
        <h2 className="text-lg font-medium mb-3">Create a new doc</h2>
        <div className="flex flex-col gap-3 md:flex-row">
          <input
            type="text"
            placeholder="Title (e.g., Getting Started)"
            className="w-full rounded-md border px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Custom slug (optional)"
            className="w-full rounded-md border px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary"
            value={customSlug}
            onChange={(e) => setCustomSlug(e.target.value)}
          />
          <button
            onClick={onCreate}
            disabled={creating || !computedSlug}
            className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-white hover:opacity-90 disabled:opacity-50"
          >
            {creating ? "Creating..." : "Create"}
          </button>
        </div>
        <p className="mt-2 text-xs text-muted-foreground">Slug: /docs/{computedSlug || "your-slug"}</p>
      </div>

      <div className="mb-4">
        <input
          type="text"
          placeholder="Search by title or tags..."
          className="w-full rounded-md border px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary"
          value={qText}
          onChange={(e) => setQText(e.target.value)}
        />
      </div>

      <div className="rounded-lg border bg-card p-2 shadow-sm">
        <div className="flex items-center justify-between px-3 py-2">
          <h2 className="text-lg font-medium">All docs</h2>
        </div>
        <ul className="divide-y">
          {filtered.map((d) => (
            <li key={d.id} className="hover:bg-muted/50">
              <Link className="block px-4 py-3" href={`/docs/${d.id}`}>
                <div className="font-medium">{d.title || d.id}</div>
                <div className="text-xs text-muted-foreground">/{d.id}</div>
              </Link>
            </li>
          ))}
          {filtered.length === 0 && (
            <li className="px-4 py-8 text-center text-sm text-muted-foreground">
              No documents match your search.
            </li>
          )}
        </ul>
      </div>
    </div>
  );
}

