"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  serverTimestamp,
  setDoc,
  updateDoc,
  deleteDoc,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [exists, setExists] = React.useState<boolean>(true);
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);
  const [loading, setLoading] = React.useState<boolean>(true);
  const [newSlug, setNewSlug] = React.useState<string>(slug);
  const [renaming, setRenaming] = React.useState<boolean>(false);
  const [deleting, setDeleting] = React.useState<boolean>(false);

  const router = useRouter();

  // Initial fetch to create a placeholder if it doesn't exist (optional)
  React.useEffect(() => {
    let mounted = true;
    (async () => {
      const refDoc = doc(db, "docs", slug);
      const snap = await getDoc(refDoc);
      if (!mounted) return;
      if (!snap.exists()) {
        setExists(false);
      } else {
        setExists(true);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [slug]);

  // Live subscription
  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      setLoading(false);
      if (!snap.exists()) {
        setExists(false);
        return;
      }
      setExists(true);
      const data = snap.data() as DocData;
      setTitle(data.title || slug);
      setContent(data.content || "");
      setTagsText((data.tags || []).join(", "));
    });
    return () => unsub();
  }, [slug]);

  // Auto-save content/title/tags (debounced)
  React.useEffect(() => {
    if (!exists) return;
    const refDoc = doc(db, "docs", slug);
    const handler = setTimeout(async () => {
      try {
        setSaving(true);
        await setDoc(
          refDoc,
          {
            title: title || slug,
            content,
            tags: tagsText
              .split(",")
              .map((t) => t.trim())
              .filter(Boolean),
            updatedAt: serverTimestamp(),
          },
          { merge: true }
        );
        setLastSavedAt(new Date());
      } finally {
        setSaving(false);
      }
    }, 600); // 600ms debounce
    return () => clearTimeout(handler);
  }, [title, content, tagsText, slug, exists]);

  async function handleUploadImage(file: File): Promise<string> {
    const path = `docs/${slug}/images/${Date.now()}-${file.name}`;
    const r = ref(storage, path);
    await uploadBytes(r, file);
    const url = await getDownloadURL(r);
    return url;
  }

  async function handleManualSave() {
    const refDoc = doc(db, "docs", slug);
    setSaving(true);
    try {
      await updateDoc(refDoc, {
        title: title || slug,
        content,
        tags: tagsText
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
        updatedAt: serverTimestamp(),
      });
      setLastSavedAt(new Date());
    } finally {
      setSaving(false);
    }
  }

  async function handleRename() {
    const target = slugify(newSlug);
    if (!target || target === slug) return;
    setRenaming(true);
    try {
      // 1) Read existing
      const fromRef = doc(db, "docs", slug);
      const toRef = doc(db, "docs", target);
      const snap = await getDoc(fromRef);
      if (!snap.exists()) {
        setRenaming(false);
        return;
      }
      const data = snap.data() as DocData;

      // 2) Create new with same data
      await setDoc(toRef, {
        ...data,
        title: data.title || target,
        updatedAt: serverTimestamp(),
      });

      // 3) Delete old
      await deleteDoc(fromRef);

      // 4) Navigate
      router.replace(`/docs/${target}`);
    } finally {
      setRenaming(false);
    }
  }

  async function handleDelete() {
    if (!confirm("Delete this document? This cannot be undone.")) return;
    setDeleting(true);
    try {
      await deleteDoc(doc(db, "docs", slug));
      router.replace("/docs");
    } finally {
      setDeleting(false);
    }
  }

  if (loading) {
    return <div className="text-sm text-muted-foreground">Loading…</div>;
  }

  if (!exists) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-semibold">Document not found</h1>
        <p className="text-sm text-muted-foreground">
          This slug does not exist yet. Create it?
        </p>
        <button
          className="rounded-md bg-primary px-3 py-2 text-white"
          onClick={async () => {
            const refDoc = doc(db, "docs", slug);
            await setDoc(refDoc, {
              title: slug,
              content: `# ${slug}\n\nStart writing your documentation here...`,
              tags: [],
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp(),
            });
          }}
        >
          Create document
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 md:flex-row md:items-center">
        <input
          className="w-full rounded-md border px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary md:max-w-md"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Document title"
        />
        <input
          className="w-full rounded-md border px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary md:max-w-md"
          value={tagsText}
          onChange={(e) => setTagsText(e.target.value)}
          placeholder="Tags (comma separated)"
        />
        <div className="ml-auto flex gap-2">
          <button
            className="rounded-md border px-3 py-2 text-sm"
            onClick={handleManualSave}
            disabled={saving}
          >
            {saving ? "Saving…" : "Save"}
          </button>
          <button
            className="rounded-md border px-3 py-2 text-sm"
            onClick={handleDelete}
            disabled={deleting}
          >
            {deleting ? "Deleting…" : "Delete"}
          </button>
        </div>
      </div>

      <div className="rounded-md border p-3">
        <label className="block text-xs font-medium text-muted-foreground mb-2">
          Rename slug
        </label>
        <div className="flex gap-2">
          <input
            className="w-full rounded-md border px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary"
            value={newSlug}
            onChange={(e) => setNewSlug(e.target.value)}
            placeholder="new-slug"
          />
          <button
            className="rounded-md border px-3 py-2 text-sm"
            onClick={handleRename}
            disabled={renaming || !newSlug}
          >
            {renaming ? "Renaming…" : "Rename"}
          </button>
        </div>
      </div>

      <MarkdownRXEditor
        value={content}
        onChange={setContent}
        onUploadImage={handleUploadImage}
        className="mt-2"
      />

      <div className="text-xs text-muted-foreground">
        {saving
          ? "Saving changes…"
          : lastSavedAt
          ? `Last saved at ${lastSavedAt.toLocaleTimeString()}`
          : "No changes yet."}
      </div>

      <div className="rounded-md border p-3">
        <h2 className="text-lg font-medium mb-2">Live Preview</h2>
        <MarkdownRXPreview value={content} />
      </div>
    </div>
  );
}
