Below is a concise walkthrough followed by a fully self-contained, compiling Go program that implements a genetic algorithm (GA) for weight budgeting with per-asset min/max bounds and a simplex (sum-to-1) constraint. The GA maximizes expected return minus a risk penalty on variance (using a covariance matrix).

Step-by-step walkthrough:
- Representation
  - Each Individual is a float64 slice of weights with per-asset bounds and total sum = 1.
- Fitness (objective)
  - Fitness = dot(w, expectedReturns) − lambda × (w^T Σ w) where Σ is the covariance matrix.
- Selection
  - Tournament selection: sample k individuals uniformly at random and choose the fittest.
- Crossover
  - Uniform crossover: each gene is independently inherited from one of the parents with probability 0.5.
- Mutation
  - Per-gene Gaussian noise applied with probability = mutationRate, followed by repair (projection) to constraints.
- Constraint handling
  - Projection onto the bounded simplex via bisection over a Lagrange multiplier, ensuring minW[i] ≤ w[i] ≤ maxW[i] and sum(w) = 1.

Code (save as main.go and run with: go run main.go):

```go
// main.go
package main

import (
	"fmt"
	"log"
	"math"
	"math/rand"
	"sort"
	"time"
)

type Individual struct {
	Weights []float64
	Fitness float64
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Example data: 5 assets (or budget categories)
	expectedReturns := []float64{0.12, 0.10, 0.07, 0.15, 0.09}
	cov := [][]float64{
		{0.10, 0.02, 0.04, 0.00, 0.01},
		{0.02, 0.08, 0.01, 0.03, 0.00},
		{0.04, 0.01, 0.12, 0.02, 0.02},
		{0.00, 0.03, 0.02, 0.15, 0.01},
		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)

	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%.6f, sum(max)=%.6f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma)
			mutate(&child2, mutationRate, mutationSigma)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			currentBest := bestIndividual(pop)
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

// Objective: maximize return - lambda * variance
func objective(w []float64, expected []float64, cov [][]float64, lambda float64) float64 {
	ret := dot(w, expected)
	variance := quadForm(w, cov)
	return ret - lambda*variance
}

// Create a random feasible weight vector summing to 1 within bounds.
func randomFeasibleWeights(n int, minW, maxW []float64) []float64 {
	w := make([]float64, n)
	sum := 0.0
	for i := 0; i < n; i++ {
		w[i] = rand.Float64() + 1e-12
		sum += w[i]
	}
	for i := 0; i < n; i++ {
		w[i] /= sum
	}
	projectToSimplexWithBounds(w, minW, maxW)
	return w
}

// Projects a vector w onto the simplex {y: sum y = 1, minW[i] <= y[i] <= maxW[i]} via bisection
// on a Lagrange multiplier tau: y_i = clip(w_i - tau, minW[i], maxW[i]) such that sum_i y_i = 1.
func projectToSimplexWithBounds(w []float64, minW, maxW []float64) {
	n := len(w)

	// Feasibility check
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0 {
		copy(w, minW)
		return
	}
	if sumMax < 1.0 {
		copy(w, maxW)
		return
	}

	// Determine tau bounds so that S(tau) spans 1
	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i]  // tau <= low => y_i = maxW[i]
		high := w[i] - minW[i] // tau >= high => y_i = minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	// Bisection on tau
	for iter := 0; iter < 80; iter++ {
		tau := 0.5 * (tauLow + tauHigh)
		sum := 0.0
		for i := 0; i < n; i++ {
			v := w[i] - tau
			if v < minW[i] {
				v = minW[i]
			}
			if v > maxW[i] {
				v = maxW[i]
			}
			sum += v
		}
		if sum > 1.0 {
			tauLow = tau
		} else {
			tauHigh = tau
		}
	}

	tau := 0.5 * (tauLow + tauHigh)
	for i := 0; i < n; i++ {
		v := w[i] - tau
		if v < minW[i] {
			v = minW[i]
		}
		if v > maxW[i] {
			v = maxW[i]
		}
		w[i] = v
	}

	// Tiny correction for numerical drift
	sum := 0.0
	freeIdx := make([]int, 0, n)
	for i := 0; i < n; i++ {
		sum += w[i]
		if w[i] > minW[i]+1e-12 && w[i] < maxW[i]-1e-12 {
			freeIdx = append(freeIdx, i)
		}
	}
	diff := 1.0 - sum
	if math.Abs(diff) > 1e-12 && len(freeIdx) > 0 {
		step := diff / float64(len(freeIdx))
		for _, j := range freeIdx {
			w[j] += step
			if w[j] < minW[j] {
				w[j] = minW[j]
			}
			if w[j] > maxW[j] {
				w[j] = maxW[j]
			}
		}
	}
}

// Tournament selection (maximization)
func tournamentSelect(pop []Individual, k int) Individual {
	best := pop[rand.Intn(len(pop))]
	for i := 1; i < k; i++ {
		cand := pop[rand.Intn(len(pop))]
		if cand.Fitness > best.Fitness {
			best = cand
		}
	}
	return best
}

// Uniform crossover
func uniformCrossover(p1, p2 Individual) (Individual, Individual) {
	n := len(p1.Weights)
	c1 := Individual{Weights: make([]float64, n)}
	c2 := Individual{Weights: make([]float64, n)}
	for i := 0; i < n; i++ {
		if rand.Intn(2) == 0 {
			c1.Weights[i] = p1.Weights[i]
			c2.Weights[i] = p2.Weights[i]
		} else {
			c1.Weights[i] = p2.Weights[i]
			c2.Weights[i] = p1.Weights[i]
		}
	}
	return c1, c2
}

// Mutation: Gaussian noise per gene with probability mutationRate
func mutate(ind *Individual, mutationRate, sigma float64) {
	for i := range ind.Weights {
		if rand.Float64() < mutationRate {
			ind.Weights[i] += rand.NormFloat64() * sigma
		}
	}
}

// Sorting helpers and utilities
func sortByFitness(pop []Individual) []Individual {
	out := make([]Individual, len(pop))
	copy(out, pop)
	sort.Slice(out, func(i, j int) bool {
		return out[i].Fitness > out[j].Fitness
	})
	return out
}

func bestIndividual(pop []Individual) Individual {
	best := pop[0]
	for i := 1; i < len(pop); i++ {
		if pop[i].Fitness > best.Fitness {
			best = pop[i]
		}
	}
	return best
}

func copyIndividual(ind Individual) Individual {
	w := make([]float64, len(ind.Weights))
	copy(w, ind.Weights)
	return Individual{Weights: w, Fitness: ind.Fitness}
}

// Math helpers
func dot(a, b []float64) float64 {
	sum := 0.0
	for i := range a {
		sum += a[i] * b[i]
	}
	return sum
}

func quadForm(w []float64, cov [][]float64) float64 {
	n := len(w)
	sum := 0.0
	for i := 0; i < n; i++ {
		row := 0.0
		for j := 0; j < n; j++ {
			row += cov[i][j] * w[j]
		}
		sum += w[i] * row
	}
	return sum
}

func pretty(w []float64) string {
	out := "["
	for i, v := range w {
		if i > 0 {
			out += ", "
		}
		out += fmt.Sprintf("%.4f", v)
	}
	out += "]"
	return out
}
```

Below is a complete, self-contained Tkinter application implementing the requested tournament scoring system. It is structured for maintainability with clear separation of data model, services, and UI, and includes inline comments. Save as tournament_scoring.py and run with Python 3.8+.

Note: The UI supports up to 4 teams (max 5 members each), up to 20 individuals, up to 5 team events and 5 individual events, results entry by ranked order, global and per-event points, “one event only” entrants, and save/load via JSON.

```python
import json
import tkinter as tk
from tkinter import ttk, messagebox, filedialog
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Optional, Tuple


# =========================
# Data Model
# =========================

@dataclass
class Team:
    id: int
    name: str
    members: List[str] = field(default_factory=list)
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Individual:
    id: int
    name: str
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Event:
    id: int
    name: str
    type: str  # "Team" or "Individual"
    genre: str = ""
    points_map: Optional[Dict[int, int]] = None  # Per-event override


# =========================
# Core Tournament State and Logic
# =========================

class TournamentData:
    """
    Core model for the tournament. Handles validation, CRUD operations,
    results storage, points aggregation, and JSON (de)serialization.
    """
    def __init__(self):
        self.teams: Dict[int, Team] = {}
        self.individuals: Dict[int, Individual] = {}
        self.events: Dict[int, Event] = {}
        # event_id -> ordered list of entrant IDs (team IDs for Team events, individual IDs for Individual events)
        self.results: Dict[int, List[int]] = {}

        # Global points table (default: F1-like Top 10)
        self.points_map: Dict[int, int] = {
            1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1
        }

        self.team_counter = 1
        self.indiv_counter = 1
        self.event_counter = 1

    # ---- Constraints ----
    def max_teams(self) -> int:
        return 4

    def max_team_members(self) -> int:
        return 5

    def max_individuals(self) -> int:
        return 20

    def max_events_per_type(self) -> int:
        # Up to 5 Team events and 5 Individual events
        return 5

    # ---- Helpers ----
    @staticmethod
    def _clean_name(value: str) -> str:
        return (value or "").strip()

    def _validate_points_map(self, points: Dict[int, int]) -> None:
        if not isinstance(points, dict) or not points:
            raise ValueError("Points map must be a non-empty dictionary.")
        for k, v in points.items():
            if not isinstance(k, int) or k <= 0:
                raise ValueError("Rank keys must be positive integers.")
            if not isinstance(v, int) or v < 0:
                raise ValueError("Point values must be non-negative integers.")
        # Ensure non-increasing points as ranks increase (1 -> 2 -> 3 ...)
        prev_points = None
        for r in sorted(points.keys()):
            if prev_points is not None and points[r] > prev_points:
                raise ValueError("Points should not increase for lower ranks.")
            prev_points = points[r]

    def get_points_for_event(self, event_id: int) -> Dict[int, int]:
        ev = self.events.get(event_id)
        if ev and ev.points_map:
            return ev.points_map
        return self.points_map

    # ---- CRUD for Teams ----
    def add_team(self, name: str, members: List[str], one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(self.teams) >= self.max_teams():
            raise ValueError("Maximum number of teams reached (4).")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")

        team_id = self.team_counter
        self.team_counter += 1
        self.teams[team_id] = Team(
            id=team_id,
            name=name,
            members=cleaned_members,
            one_event_only=one_event_only,
            chosen_event_id=chosen_event_id
        )
        return team_id

    def edit_team(self, tid: int, name: str, members: List[str], one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() and t.id != tid for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")

        team = self.teams[tid]
        team.name = name
        team.members = cleaned_members
        team.one_event_only = one_event_only
        team.chosen_event_id = chosen_event_id

    def remove_team(self, tid: int) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        # Remove from Team event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Team":
                self.results[ev_id] = [pid for pid in places if pid != tid]
        del self.teams[tid]

    # ---- CRUD for Individuals ----
    def add_individual(self, name: str, one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if len(self.individuals) >= self.max_individuals():
            raise ValueError("Maximum number of individuals reached (20).")
        if any(i.name.lower() == name.lower() for i in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")

        iid = self.indiv_counter
        self.indiv_counter += 1
        self.individuals[iid] = Individual(
            id=iid,
            name=name,
            one_event_only=one_event_only,
            chosen_event_id=chosen_event_id
        )
        return iid

    def edit_individual(self, iid: int, name: str, one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if any(p.name.lower() == name.lower() and p.id != iid for p in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")

        person = self.individuals[iid]
        person.name = name
        person.one_event_only = one_event_only
        person.chosen_event_id = chosen_event_id

    def remove_individual(self, iid: int) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        # Remove from Individual event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Individual":
                self.results[ev_id] = [pid for pid in places if pid != iid]
        del self.individuals[iid]

    # ---- CRUD for Events ----
    def add_event(self, name: str, etype: str, genre: str = "", points_map: Optional[Dict[int, int]] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        count_type = sum(1 for e in self.events.values() if e.type == etype)
        if count_type >= self.max_events_per_type():
            raise ValueError(f"Maximum number of {etype} events reached (5).")
        if any(e.name.lower() == name.lower() for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)

        eid = self.event_counter
        self.event_counter += 1
        self.events[eid] = Event(
            id=eid,
            name=name,
            type=etype,
            genre=self._clean_name(genre),
            points_map=points_map
        )
        return eid

    def edit_event(self, eid: int, name: str, etype: str, genre: str, points_map: Optional[Dict[int, int]]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if any(e.name.lower() == name.lower() and e.id != eid for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)

        old = self.events[eid]
        # If type changes, clear results to avoid cross-type mismatch
        if old.type != etype and eid in self.results:
            self.results[eid] = []
        old.name = name
        old.type = etype
        old.genre = self._clean_name(genre)
        old.points_map = points_map

    def remove_event(self, eid: int) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        # Remove results for this event
        self.results.pop(eid, None)
        # Clear chosen_event_id references in entrants
        for t in self.teams.values():
            if t.chosen_event_id == eid:
                t.chosen_event_id = None
        for i in self.individuals.values():
            if i.chosen_event_id == eid:
                i.chosen_event_id = None
        del self.events[eid]

    # ---- Results & Points ----
    def set_event_results(self, eid: int, ordered_ids: List[int]) -> None:
        """
        Save ordered results for event eid after validating entrant types,
        duplicates, and 'one event only' constraints.
        """
        ev = self.events.get(eid)
        if ev is None:
            raise ValueError("Event not found.")

        # Validate entrants' type membership and "one event only" constraints
        seen = set()
        for pid in ordered_ids:
            if pid in seen:
                raise ValueError("Duplicate entrant in results.")
            seen.add(pid)
            if ev.type == "Team":
                if pid not in self.teams:
                    raise ValueError("Unknown team ID in results.")
                team = self.teams[pid]
                if team.one_event_only:
                    # If a chosen event exists, enforce it
                    if team.chosen_event_id is not None and team.chosen_event_id != eid:
                        raise ValueError(f"Team '{team.name}' is one-event-only and restricted to its chosen event.")
            else:
                if pid not in self.individuals:
                    raise ValueError("Unknown individual ID in results.")
                person = self.individuals[pid]
                if person.one_event_only:
                    if person.chosen_event_id is not None and person.chosen_event_id != eid:
                        raise ValueError(f"Individual '{person.name}' is one-event-only and restricted to their chosen event.")

        # Auto-assign chosen_event_id for one-event-only entrants without a chosen event
        for pid in ordered_ids:
            if ev.type == "Team":
                t = self.teams[pid]
                if t.one_event_only and t.chosen_event_id is None:
                    t.chosen_event_id = eid
            else:
                p = self.individuals[pid]
                if p.one_event_only and p.chosen_event_id is None:
                    p.chosen_event_id = eid

        self.results[eid] = ordered_ids[:]

    def compute_points_totals(self) -> Tuple[Dict[int, int], Dict[int, int], Dict[int, int], Dict[int, int]]:
        """
        Compute points totals for teams and individuals.
        Returns:
          team_points: team_id -> points
          team_events_entered: team_id -> count
          indiv_points: indiv_id -> points
          indiv_events_entered: indiv_id -> count
        """
        team_points: Dict[int, int] = {tid: 0 for tid in self.teams}
        team_events_entered: Dict[int, int] = {tid: 0 for tid in self.teams}
        indiv_points: Dict[int, int] = {iid: 0 for iid in self.individuals}
        indiv_events_entered: Dict[int, int] = {iid: 0 for iid in self.individuals}

        for eid, ordered in self.results.items():
            ev = self.events.get(eid)
            if not ev:
                continue
            points_map = self.get_points_for_event(eid)
            # Count entrants for events_entered and award points by rank
            if ev.type == "Team":
                for rank, pid in enumerate(ordered, start=1):
                    if pid in team_events_entered:
                        team_events_entered[pid] += 1
                    pts = points_map.get(rank, 0)
                    if pid in team_points:
                        team_points[pid] += pts
            else:
                for rank, pid in enumerate(ordered, start=1):
                    if pid in indiv_events_entered:
                        indiv_events_entered[pid] += 1
                    pts = points_map.get(rank, 0)
                    if pid in indiv_points:
                        indiv_points[pid] += pts

        return team_points, team_events_entered, indiv_points, indiv_events_entered

    # ---- Serialization ----
    def to_json(self) -> str:
        payload = {
            "teams": [asdict(t) for t in self.teams.values()],
            "individuals": [asdict(i) for i in self.individuals.values()],
            "events": [asdict(e) for e in self.events.values()],
            "results": {str(k): v for k, v in self.results.items()},
            "points_map": self.points_map,
            "counters": {
                "team": self.team_counter,
                "individual": self.indiv_counter,
                "event": self.event_counter
            }
        }
        return json.dumps(payload, indent=2)

    def load_json(self, text: str) -> None:
        data = json.loads(text)

        # Validate basic structure
        if not isinstance(data, dict):
            raise ValueError("Invalid file structure.")

        # Load points (validate)
        points_map = data.get("points_map")
        if points_map:
            points_map_int = {int(k) if isinstance(k, str) else k: v for k, v in points_map.items()}
            self._validate_points_map(points_map_int)
            self.points_map = points_map_int

        # Load events
        self.events.clear()
        for ed in data.get("events", []):
            if not isinstance(ed, dict):
                raise ValueError("Invalid event entry.")
            pid_map = ed.get("points_map")
            if pid_map:
                pid_map = {int(k) if isinstance(k, str) else k: v for k, v in pid_map.items()}
                self._validate_points_map(pid_map)
            e = Event(
                id=int(ed["id"]),
                name=self._clean_name(ed["name"]),
                type=ed["type"],
                genre=self._clean_name(ed.get("genre", "")),
                points_map=pid_map
            )
            if e.type not in ("Team", "Individual"):
                raise ValueError("Event type must be 'Team' or 'Individual'.")
            self.events[e.id] = e

        # Load teams
        self.teams.clear()
        for td in data.get("teams", []):
            if not isinstance(td, dict):
                raise ValueError("Invalid team entry.")
            members = [self._clean_name(m) for m in td.get("members", []) if self._clean_name(m)]
            if not members or len(members) > self.max_team_members():
                raise ValueError("Invalid team members.")
            chosen_eid = td.get("chosen_event_id")
            if chosen_eid is not None:
                if chosen_eid not in self.events or self.events[chosen_eid].type != "Team":
                    chosen_eid = None  # sanitize
            t = Team(
                id=int(td["id"]),
                name=self._clean_name(td["name"]),
                members=members,
                one_event_only=bool(td.get("one_event_only", False)),
                chosen_event_id=chosen_eid
            )
            self.teams[t.id] = t

        # Load individuals
        self.individuals.clear()
        for idd in data.get("individuals", []):
            if not isinstance(idd, dict):
                raise ValueError("Invalid individual entry.")
            chosen_eid = idd.get("chosen_event_id")
            if chosen_eid is not None:
                if chosen_eid not in self.events or self.events[chosen_eid].type != "Individual":
                    chosen_eid = None  # sanitize
            i = Individual(
                id=int(idd["id"]),
                name=self._clean_name(idd["name"]),
                one_event_only=bool(idd.get("one_event_only", False)),
                chosen_event_id=chosen_eid
            )
            self.individuals[i.id] = i

        # Load results (validate types and ids)
        self.results.clear()
        raw_results = data.get("results", {})
        for k, v in raw_results.items():
            eid = int(k)
            if eid not in self.events:
                continue
            ev = self.events[eid]
            if not isinstance(v, list):
                raise ValueError("Invalid results format.")
            # Validate entrants exist and are of correct type
            cleaned: List[int] = []
            seen = set()
            for pid in v:
                pid = int(pid)
                if pid in seen:
                    raise ValueError("Duplicate entrant in saved results.")
                seen.add(pid)
                if ev.type == "Team":
                    if pid not in self.teams:
                        raise ValueError("Unknown team ID in saved results.")
                else:
                    if pid not in self.individuals:
                        raise ValueError("Unknown individual ID in saved results.")
                cleaned.append(pid)
            self.results[eid] = cleaned

        # Restore counters conservatively (ensure no collisions)
        counters = data.get("counters", {})
        self.team_counter = max([counters.get("team", 1), *(self.teams.keys() or [0])]) + 1
        self.indiv_counter = max([counters.get("individual", 1), *(self.individuals.keys() or [0])]) + 1
        self.event_counter = max([counters.get("event", 1), *(self.events.keys() or [0])]) + 1


