def parse_points_string(s: str) -> Dict[int, int]:
    """
    Parse a points string like "1:25,2:18,3:15" into {1:25, 2:18, 3:15}.
    Whitespace is allowed. Empty string returns {}.
    Raises ValueError on invalid format.
    """
    s = (s or "").strip()
    if not s:
        return {}
    result: Dict[int, int] = {}
    parts = [p.strip() for p in s.split(",") if p.strip()]
    for p in parts:
        if ":" not in p:
            raise ValueError(f"Invalid points pair '{p}'. Use 'rank:points'.")
        k_str, v_str = [x.strip() for x in p.split(":", 1)]
        if not k_str.isdigit() or not v_str.lstrip("-").isdigit():
            raise ValueError(f"Invalid integer in '{p}'.")
        rank = int(k_str)
        pts = int(v_str)
        if rank <= 0 or pts < 0:
            raise ValueError(f"Rank must be >0 and points >=0 in '{p}'.")
        result[rank] = pts
    # Enforce non-increasing points by rank
    prev = None
    for r in sorted(result.keys()):
        if prev is not None and result[r] > result[prev]:
            raise ValueError("Points should not increase for lower ranks.")
        prev = r
    return result


def points_to_string(points: Dict[int, int]) -> str:
    if not points:
        return ""
    pairs = [f"{r}:{points[r]}" for r in sorted(points.keys())]
    return ",".join(pairs)


