class TournamentApp(tk.Tk):
    """
    Main Tkinter application shell with tabs:
    - Participants (Teams and Individuals)
    - Events
    - Results
    - Leaderboards
    - Points
    Includes File menu: New, Open, Save, Save As, Exit.
    """
    def __init__(self):
        super().__init__()
        self.title("E-Sports Tournament Scoring")
        self.geometry("1100x720")

        self.data = TournamentData()
        self.current_file: Optional[str] = None

        self._build_menu()
        self._build_tabs()

    # ---- Menu ----
    def _build_menu(self):
        menubar = tk.Menu(self)
        file_menu = tk.Menu(menubar, tearoff=False)
        file_menu.add_command(label="New", command=self.action_new)
        file_menu.add_command(label="Open...", command=self.action_open)
        file_menu.add_command(label="Save", command=self.action_save)
        file_menu.add_command(label="Save As...", command=self.action_save_as)
        file_menu.add_separator()
        file_menu.add_command(label="Exit", command=self.destroy)
        menubar.add_cascade(label="File", menu=file_menu)
        self.config(menu=menubar)

    # ---- Tabs ----
    def _build_tabs(self):
        self.nb = ttk.Notebook(self)
        self.nb.pack(fill="both", expand=True, padx=6, pady=6)

        self.tab_participants = ttk.Frame(self.nb)
        self.tab_events = ttk.Frame(self.nb)
        self.tab_results = ttk.Frame(self.nb)
        self.tab_leaderboards = ttk.Frame(self.nb)
        self.tab_points = ttk.Frame(self.nb)

        self.nb.add(self.tab_participants, text="Participants")
        self.nb.add(self.tab_events, text="Events")
        self.nb.add(self.tab_results, text="Results")
        self.nb.add(self.tab_leaderboards, text="Leaderboards")
        self.nb.add(self.tab_points, text="Points")

        self._build_participants_tab()
        self._build_events_tab()
        self._build_results_tab()
        self._build_leaderboards_tab()
        self._build_points_tab()

    # =========================
    # Participants Tab
    # =========================
    def _build_participants_tab(self):
        container = self.tab_participants
        container.columnconfigure(0, weight=1)
        container.columnconfigure(1, weight=1)
        container.rowconfigure(0, weight=1)

        # Teams Panel
        team_frame = ttk.LabelFrame(container, text="Teams")
        team_frame.grid(row=0, column=0, sticky="nsew", padx=6, pady=6)
        team_frame.columnconfigure(0, weight=1)
        team_frame.columnconfigure(1, weight=1)
        team_frame.rowconfigure(3, weight=1)

        # Team list
        self.team_list = tk.Listbox(team_frame, height=12)
        self.team_list.grid(row=0, column=0, columnspan=2, sticky="nsew", padx=4, pady=4)
        self.team_list.bind("<<ListboxSelect>>", lambda e: self.on_select_team())

        # Team form
        ttk.Label(team_frame, text="Team Name:").grid(row=1, column=0, sticky="e", padx=4, pady=2)
        self.team_name_var = tk.StringVar()
        ttk.Entry(team_frame, textvariable=self.team_name_var).grid(row=1, column=1, sticky="we", padx=4, pady=2)

        ttk.Label(team_frame, text="Members (up to 5, one per line):").grid(row=2, column=0, sticky="ne", padx=4, pady=2)
        self.team_members = tk.Text(team_frame, height=6)
        self.team_members.grid(row=2, column=1, sticky="nsew", padx=4, pady=2)

        self.team_one_event_var = tk.BooleanVar()
        ttk.Checkbutton(team_frame, text="One event only", variable=self.team_one_event_var).grid(row=3, column=0, sticky="w", padx=4, pady=2)

        ttk.Label(team_frame, text="Chosen Event (optional):").grid(row=4, column=0, sticky="e", padx=4, pady=2)
        self.team_chosen_event_var = tk.StringVar()
        self.team_chosen_event_cb = ttk.Combobox(team_frame, textvariable=self.team_chosen_event_var, state="readonly")
        self.team_chosen_event_cb.grid(row=4, column=1, sticky="we", padx=4, pady=2)

        # Team buttons
        bframe_t = ttk.Frame(team_frame)
        bframe_t.grid(row=5, column=0, columnspan=2, sticky="e", padx=4, pady=4)
        ttk.Button(bframe_t, text="Add", command=self.action_add_team).pack(side="left", padx=2)
        ttk.Button(bframe_t, text="Update", command=self.action_update_team).pack(side="left", padx=2)
        ttk.Button(bframe_t, text="Remove", command=self.action_remove_team).pack(side="left", padx=2)
        ttk.Button(bframe_t, text="Clear", command=self.action_clear_team_form).pack(side="left", padx=2)

        # Individuals Panel
        indiv_frame = ttk.LabelFrame(container, text="Individuals")
        indiv_frame.grid(row=0, column=1, sticky="nsew", padx=6, pady=6)
        indiv_frame.columnconfigure(0, weight=1)
        indiv_frame.columnconfigure(1, weight=1)
        indiv_frame.rowconfigure(2, weight=1)

        # Individual list
        self.indiv_list = tk.Listbox(indiv_frame, height=12)
        self.indiv_list.grid(row=0, column=0, columnspan=2, sticky="nsew", padx=4, pady=4)
        self.indiv_list.bind("<<ListboxSelect>>", lambda e: self.on_select_individual())

        # Individual form
        ttk.Label(indiv_frame, text="Name:").grid(row=1, column=0, sticky="e", padx=4, pady=2)
        self.indiv_name_var = tk.StringVar()
        ttk.Entry(indiv_frame, textvariable=self.indiv_name_var).grid(row=1, column=1, sticky="we", padx=4, pady=2)

        self.indiv_one_event_var = tk.BooleanVar()
        ttk.Checkbutton(indiv_frame, text="One event only", variable=self.indiv_one_event_var).grid(row=2, column=0, sticky="w", padx=4, pady=2)

        ttk.Label(indiv_frame, text="Chosen Event (optional):").grid(row=3, column=0, sticky="e", padx=4, pady=2)
        self.indiv_chosen_event_var = tk.StringVar()
        self.indiv_chosen_event_cb = ttk.Combobox(indiv_frame, textvariable=self.indiv_chosen_event_var, state="readonly")
        self.indiv_chosen_event_cb.grid(row=3, column=1, sticky="we", padx=4, pady=2)

        # Individual buttons
        bframe_i = ttk.Frame(indiv_frame)
        bframe_i.grid(row=4, column=0, columnspan=2, sticky="e", padx=4, pady=4)
        ttk.Button(bframe_i, text="Add", command=self.action_add_individual).pack(side="left", padx=2)
        ttk.Button(bframe_i, text="Update", command=self.action_update_individual).pack(side="left", padx=2)
        ttk.Button(bframe_i, text="Remove", command=self.action_remove_individual).pack(side="left", padx=2)
        ttk.Button(bframe_i, text="Clear", command=self.action_clear_individual_form).pack(side="left", padx=2)

        # Initialize lists
        self.refresh_team_list()
        self.refresh_indiv_list()
        self.refresh_chosen_event_combos()

    # ---- Participants Handlers ----
    def refresh_team_list(self):
        self.team_list.delete(0, tk.END)
        for t in sorted(self.data.teams.values(), key=lambda x: x.name.lower()):
            self.team_list.insert(tk.END, f"{t.id}: {t.name} ({len(t.members)} members)")

    def refresh_indiv_list(self):
        self.indiv_list.delete(0, tk.END)
        for p in sorted(self.data.individuals.values(), key=lambda x: x.name.lower()):
            self.indiv_list.insert(tk.END, f"{p.id}: {p.name}")

    def refresh_chosen_event_combos(self):
        # Teams: only Team events
        team_events = [(e.id, e.name) for e in self.data.events.values() if e.type == "Team"]
        self.team_chosen_event_cb["values"] = [f"{eid}: {name}" for eid, name in sorted(team_events, key=lambda x: x[1].lower())]
        # Individuals: only Individual events
        indiv_events = [(e.id, e.name) for e in self.data.events.values() if e.type == "Individual"]
        self.indiv_chosen_event_cb["values"] = [f"{eid}: {name}" for eid, name in sorted(indiv_events, key=lambda x: x[1].lower())]

    def _parse_selected_team_id(self) -> Optional[int]:
        sel = self.team_list.curselection()
        if not sel:
            return None
        text = self.team_list.get(sel[0])
        try:
            return int(text.split(":")[0])
        except Exception:
            return None

    def _parse_selected_individual_id(self) -> Optional[int]:
        sel = self.indiv_list.curselection()
        if not sel:
            return None
        text = self.indiv_list.get(sel[0])
        try:
            return int(text.split(":")[0])
        except Exception:
            return None

    def _parse_combo_event_id(self, combo_var: tk.StringVar) -> Optional[int]:
        v = combo_var.get().strip()
        if not v:
            return None
        try:
            return int(v.split(":")[0])
        except Exception:
            return None

    def on_select_team(self):
        tid = self._parse_selected_team_id()
        if tid is None or tid not in self.data.teams:
            return
        t = self.data.teams[tid]
        self.team_name_var.set(t.name)
        self.team_members.delete("1.0", tk.END)
        self.team_members.insert(tk.END, "\n".join(t.members))
        self.team_one_event_var.set(t.one_event_only)
        if t.chosen_event_id and t.chosen_event_id in self.data.events:
            e = self.data.events[t.chosen_event_id]
            self.team_chosen_event_var.set(f"{e.id}: {e.name}")
        else:
            self.team_chosen_event_var.set("")

    def action_add_team(self):
        try:
            name = self.team_name_var.get().strip()
            members = [m.strip() for m in self.team_members.get("1.0", tk.END).splitlines() if m.strip()]
            one_event = self.team_one_event_var.get()
            chosen_eid = self._parse_combo_event_id(self.team_chosen_event_var)
            if chosen_eid is not None:
                ev = self.data.events.get(chosen_eid)
                if not ev or ev.type != "Team":
                    raise ValueError("Chosen event must be a Team event.")
            self.data.add_team(name, members, one_event, chosen_eid)
            self.refresh_team_list()
            self.refresh_results_entrants()  # in case Results tab is open
            messagebox.showinfo("Success", "Team added.")
        except Exception as ex:
            messagebox.showerror("Error", str(ex))

    def action_update_team(self):
        try:
            tid = self._parse_selected_team_id()
            if tid is None:
                raise ValueError("Select a team to update.")
            name = self.team_name_var.get().strip()
            members = [m.strip() for m in self.team_members.get("1.0", tk.END).splitlines() if m.strip()]
            one_event = self.team_one_event_var.get()
            chosen_eid = self._parse_combo_event_id(self.team_chosen_event_var)
            if chosen_eid is not None:
                ev = self.data.events.get(chosen_eid)
                if not ev or ev.type != "Team":
                    raise ValueError("Chosen event must be a Team event.")
            self.data.edit_team(tid, name, members, one_event, chosen_eid)
            self.refresh_team_list()
            self.refresh_results_entrants()
            messagebox.showinfo("Success", "Team updated.")
        except Exception as ex:
            messagebox.showerror("Error", str(ex))

    def action_remove_team(self):
        try:
            tid = self._parse_selected_team_id()
            if tid is None:
                raise ValueError("Select a team to remove.")
            if messagebox.askyesno("Confirm", "Remove selected team?"):
                self.data.remove_team(tid)
                self.refresh_team_list()
                self.refresh_results_entrants()
                self.action_clear_team_form()
        except Exception as ex:
            messagebox.showerror("Error", str(ex))

    def action_clear_team_form(self):
