    def refresh_results_event_combo(self):
        values = [f"{e.id}: {e.name}" for e in sorted(self.data.events.values(), key=lambda x: x.name.lower())]
        self.results_event_cb["values"] = values
        # Preserve selection if possible
        cur = self.results_event_var.get()
        if cur not in values:
            self.results_event_var.set(values[0] if values else "")

    def _parse_selected_results_event_id(self) -> Optional[int]:
        v = self.results_event_var.get().strip()
        if not v:
            return None
        try:
            return int(v.split(":")[0])
        except Exception:
            return None

    def refresh_results_entrants(self):
        # Refresh entrants lists based on current event selection
        self.refresh_results_event_combo()
        self.load_event_results_ui()

    def load_event_results_ui(self):
        self.available_list.delete(0, tk.END)
        self.ordered_list.delete(0, tk.END)
        eid = self._parse_selected_results_event_id()
        if eid is None or eid not in self.data.events:
            return
        ev = self.data.events[eid]
        # Available entrants by type
        if ev.type == "Team":
            entries = [(t.id, t.name) for t in self.data.teams.values()]
        else:
            entries = [(p.id, p.name) for p in self.data.individuals.values()]
        for pid, name in sorted(entries, key=lambda x: x[1].lower()):
            self.available_list.insert(tk.END, f"{pid}: {name}")
        # Ordered results (existing)
        ordered = self.data.results.get(eid, [])
        for pid in ordered:
            name = self._resolve_name(ev.type, pid)
            self.ordered_list.insert(tk.END, f"{pid}: {name}")

    def _parse_listbox_ids(self, lb: tk.Listbox) -> List[int]:
        ids: List[int] = []
        for i in range(lb.size()):
            text = lb.get(i)
            try:
                ids.append(int(text.split(":")[0]))
            except Exception:
                pass
        return ids

    def _resolve_name(self, etype: str, pid: int) -> str:
        if etype == "Team":
            return self.data.teams.get(pid).name if pid in self.data.teams else f"Team {pid}"
        return self.data.individuals.get(pid).name if pid in self.data.individuals else f"Player {pid}"

    def action_results_add(self):
        # Move selected from available_list to ordered_list
        sels = list(self.available_list.curselection())
        for idx in sels:
            item = self.available_list.get(idx)
            if item not in self.ordered_list.get(0, tk.END):
                self.ordered_list.insert(tk.END, item)

    def action_results_remove(self):
        # Remove selected from ordered_list
        sels = list(self.ordered_list.curselection())
        for idx in reversed(sels):
            self.ordered_list.delete(idx)

    def action_results_up(self):
        sels = list(self.ordered_list.curselection())
        if not sels:
            return
        for idx in sels:
            if idx == 0:
                continue
            text = self.ordered_list.get(idx)
            self.ordered_list.delete(idx)
            self.ordered_list.insert(idx - 1, text)
            self.ordered_list.selection_set(idx - 1)

    def action_results_down(self):
        sels = list(self.ordered_list.curselection())
        if not sels:
            return
        size = self.ordered_list.size()
        for idx in reversed(sels):
            if idx >= size - 1:
                continue
            text = self.ordered_list.get(idx)
            self.ordered_list.delete(idx)
            self.ordered_list.insert(idx + 1, text)
            self.ordered_list.selection_set(idx + 1)

    def action_clear_ordered(self):
        self.ordered_list.delete(0, tk.END)

    def action_save_results(self):
        try:
            eid = self._parse_selected_results_event_id()
            if eid is None:
                raise ValueError("Select an event to save results.")
            ev = self.data.events.get(eid)
            if not ev:
                raise ValueError("Event not found.")
            ordered_ids = self._parse_listbox_ids(self.ordered_list)

            # Validate "one event only" with chosen event enforcement
            # Detailed checks are in data.set_event_results
            self.data.set_event_results(eid, ordered_ids)

            messagebox.showinfo("Success", "Results saved.")
            # Update leaderboards immediately
            self.refresh_leaderboards()
        except Exception as ex:
            messagebox.showerror("Error", str(ex))

