        f.rowconfigure(1, weight=1)

        ttk.Label(f, text="Team Leaderboard").grid(row=0, column=0, padx=6, pady=6, sticky="w")
        ttk.Label(f, text="Individual Leaderboard").grid(row=0, column=1, padx=6, pady=6, sticky="w")

        cols = ("rank", "name", "points", "events")
        self.team_tree = ttk.Treeview(f, columns=cols, show="headings", height=16)
        for c, txt, w in zip(cols, ["Rank", "Team", "Points", "Events"], [60, 220, 80, 80]):
            self.team_tree.heading(c, text=txt)
            self.team_tree.column(c, width=w, anchor="center" if c != "name" else "w")
        self.team_tree.grid(row=1, column=0, sticky="nsew", padx=6, pady=6)

        self.indiv_tree = ttk.Treeview(f, columns=cols, show="headings", height=16)
        for c, txt, w in zip(cols, ["Rank", "Individual", "Points", "Events"], [60, 220, 80, 80]):
            self.indiv_tree.heading(c, text=txt)
            self.indiv_tree.column(c, width=w, anchor="center" if c != "name" else "w")
        self.indiv_tree.grid(row=1, column=1, sticky="nsew", padx=6, pady=6)

        b = ttk.Frame(f)
        b.grid(row=2, column=0, columnspan=2, sticky="e", padx=6, pady=6)
        ttk.Button(b, text="Refresh", command=self.refresh_leaderboards).pack(side="right")

        self.refresh_leaderboards()

    def refresh_leaderboards(self):
        for tree in (self.team_tree, self.indiv_tree):
            for i in tree.get_children():
                tree.delete(i)

        team_pts, team_ev, indiv_pts, indiv_ev = self.data.compute_points_totals()

        # Teams
        sorted_teams = sorted(self.data.teams.values(), key=lambda t: (-team_pts.get(t.id, 0), t.name.lower()))
        rank = 1
        for t in sorted_teams:
            self.team_tree.insert("", tk.END, values=(rank, t.name, team_pts.get(t.id, 0), team_ev.get(t.id, 0)))
            rank += 1

        # Individuals
        sorted_indiv = sorted(self.data.individuals.values(), key=lambda p: (-indiv_pts.get(p.id, 0), p.name.lower()))
        rank = 1
        for p in sorted_indiv:
            self.indiv_tree.insert("", tk.END, values=(rank, p.name, indiv_pts.get(p.id, 0), indiv_ev.get(p.id, 0)))
            rank += 1

