    def action_apply_scheme(self):
        try:
            scheme = self.scheme_var.get()
            if scheme == "F1":
                pm = {1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1}
            elif scheme == "Top8":
                pm = {1: 10, 2: 8, 3: 6, 4: 5, 5: 4, 6: 3, 7: 2, 8: 1}
            elif scheme == "WTA":
                pm = {1: 10, 2: 0, 3: 0, 4: 0, 5: 0}
            else:
                raise ValueError("Unknown scheme.")
            self.data._validate_points_map(pm)
            self.data.points_map = pm
            self.points_edit_var.set(points_to_string(self.data.points_map))
            self._refresh_points_view()
            messagebox.showinfo("Success", "Global points scheme applied.")
            self.refresh_leaderboards()
        except Exception as ex:
            messagebox.showerror("Error", str(ex))

    def action_apply_custom_points(self):
        try:
            pm = parse_points_string(self.points_edit_var.get())
            if not pm:
                raise ValueError("Custom points cannot be empty.")
            self.data._validate_points_map(pm)
            self.data.points_map = pm
            self._refresh_points_view()
            messagebox.showinfo("Success", "Custom global points applied.")
            self.refresh_leaderboards()
        except Exception as ex:
            messagebox.showerror("Error", str(ex))

    def _refresh_points_view(self):
        self.points_view.config(state="normal")
        self.points_view.delete("1.0", tk.END)
        for r in sorted(self.data.points_map.keys()):
            self.points_view.insert(tk.END, f"Rank {r}: {self.data.points_map[r]}\n")
        self.points_view.config(state="disabled")

    # =========================
    # File Menu Actions
    # =========================
    def action_new(self):
        if not messagebox.askyesno("Confirm", "Start a new tournament? Unsaved changes will be lost."):
            return
        self.data = TournamentData()
        self.current_file = None
        self._reload_all_ui()

    def action_open(self):
        path = filedialog.askopenfilename(title="Open Tournament", filetypes=[("JSON Files", "*.json")])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                text = f.read()
            td = TournamentData()
            td.load_json(text)
            self.data = td
            self.current_file = path
            self._reload_all_ui()
            messagebox.showinfo("Loaded", "Tournament loaded successfully.")
        except Exception as ex:
            messagebox.showerror("Error", f"Failed to load file:\n{ex}")

    def action_save(self):
        if not self.current_file:
            self.action_save_as()
            return
        try:
            with open(self.current_file, "w", encoding="utf-8") as f:
                f.write(self.data.to_json())
            messagebox.showinfo("Saved", "Tournament saved.")
        except Exception as ex:
            messagebox.showerror("Error", f"Failed to save file:\n{ex}")

    def action_save_as(self):
        path = filedialog.asksaveasfilename(title="Save Tournament As", defaultextension=".json", filetypes=[("JSON Files", "*.json")])
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(self.data.to_json())
            self.current_file = path
            messagebox.showinfo("Saved", "Tournament saved.")
        except Exception as ex:
            messagebox.showerror("Error", f"Failed to save file:\n{ex}")

    # ---- UI Refresh Helper ----
    def _reload_all_ui(self):
        # Participants
        self.refresh_team_list()
